do $$begin if current_database()<>'byus_clean'or inet_server_addr()is not null then raise exception 'Disposable Unixsocket byus_clean required';end if;end $$;
begin;
create function pg_temp.heart_assert(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',message;end if;raise notice 'PASS %',message;end $$;
create function pg_temp.heart_error(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected %',expected;end $$;
do $$declare a uuid:='e8000000-0000-4000-8000-000000000001';b uuid:='e8000000-0000-4000-8000-000000000002';c uuid:='e8000000-0000-4000-8000-000000000003';creator uuid:='e8000000-0000-4000-8000-000000000010';key uuid:=extensions.gen_random_uuid();send_key uuid:=extensions.gen_random_uuid();cancel_key uuid:=extensions.gen_random_uuid();r jsonb;replay jsonb;cursor bigint;source uuid;begin
 perform pg_temp.heart_assert(not exists(select 1 from public.heart_support_upgrade_snapshot s where s.wallet is distinct from public.read_owned_mobile_fan_economy_wallet(s.owner,'heart-fixture')),'upgrade_old_wallet_and_rights_exact');
 perform pg_temp.heart_error(format('select public.exchange_owned_mobile_fan_economy(%L,%L,''heart-fixture'',''support_voucher'',''heart-v1'',1)',a,key),'INSUFFICIENT_BALANCE');
 r:=public.exchange_owned_mobile_fan_economy(b,key,'heart-fixture','support_voucher','heart-v1',1);replay:=public.exchange_owned_mobile_fan_economy(b,key,'heart-fixture','support_voucher','heart-v1',1);
 perform pg_temp.heart_assert(r->>'pointsSpent'='100'and replay->>'replayed'='true'and(r-'replayed')=(replay-'replayed')and public.mobile_fan_economy_balance(b,creator,'fan_point')=0 and public.mobile_fan_economy_balance(b,creator,'support_voucher')=1,'100P_atomic_exchange_and_replay');
 perform public.exchange_owned_mobile_fan_economy(c,extensions.gen_random_uuid(),'heart-fixture','support_voucher','heart-v1',2);
 perform pg_temp.heart_assert(public.mobile_fan_economy_balance(c,creator,'fan_point')=50 and public.mobile_fan_economy_balance(c,creator,'support_voucher')=2,'250P_preserves_50P_remainder');
 perform pg_temp.heart_assert(not exists(select 1 from jsonb_array_elements(public.read_owned_mobile_fan_economy_history(b,'heart-fixture',100)->'entries')e where e->>'asset'='support_voucher')and exists(select 1 from jsonb_array_elements(public.read_owned_mobile_fan_support_history(b,'heart-fixture',100)->'entries')e where e->>'asset'='support_voucher'),'old_history_3assets_new_history4');
 perform pg_temp.heart_assert(jsonb_array_length(public.read_owned_mobile_fan_support_rankings(a)->'items')=0,'unused_hearts_never_rank');
 perform public.send_owned_mobile_fan_support(c,extensions.gen_random_uuid(),'heart-fixture','heart-v1',1);
 perform pg_temp.heart_assert(jsonb_array_length(public.read_owned_mobile_fan_support_rankings(a)->'items')=0,'private_fan_support_not_public');
 r:=public.send_owned_mobile_fan_support(b,send_key,'heart-fixture','heart-v1',1);replay:=public.send_owned_mobile_fan_support(b,send_key,'heart-fixture','heart-v1',1);
 perform pg_temp.heart_assert(r->>'supportKrw'='100'and r->>'units'='1'and replay->>'replayed'='true'and public.mobile_fan_economy_balance(b,creator,'support_voucher')=0 and(select count(*)from public.mobile_fan_support_contributions where app_user_id=b)=1,'one_send_one_immutable_contribution');
 perform pg_temp.heart_assert(public.read_owned_mobile_fan_economy_request(a,send_key,'support')->>'status'='unknown','other_owner_cannot_read_original_request');
 perform pg_temp.heart_error(format('select public.send_owned_mobile_fan_support(%L,%L,''heart-fixture'',''heart-v1'',1)',b,extensions.gen_random_uuid()),'INSUFFICIENT_BALANCE');
 perform pg_temp.heart_error(format('select public.send_owned_mobile_fan_support(%L,%L,''heart-fixture'',''heart-v1'',1)',b,key),'REQUEST_CONFLICT');
 perform public.cancel_owned_mobile_fan_economy_request(c,cancel_key,'support','{"celebritySlug":"heart-fixture","policyVersion":"heart-v1","units":1}');
 perform pg_temp.heart_error(format('select public.send_owned_mobile_fan_support(%L,%L,''heart-fixture'',''heart-v1'',1)',c,cancel_key),'REQUEST_CANCELLED');
 perform pg_temp.heart_assert(public.read_owned_mobile_fan_economy_request(c,cancel_key,'support')->>'status'='cancelled','cancelled_send_recovery');
 perform pg_temp.heart_error(format('select public.send_owned_mobile_fan_support(%L,%L,''heart-fixture'',''old'',1)',c,extensions.gen_random_uuid()),'POLICY_CHANGED');
 perform pg_temp.heart_error(format('select public.send_owned_mobile_fan_support(%L,%L,''heart-fixture'',''heart-v1'',0)',c,extensions.gen_random_uuid()),'INVALID');
 r:=public.read_owned_mobile_fan_support_fans(a,'heart-fixture');
 perform pg_temp.heart_assert(r#>>'{items,0,profileId}'=b::text and r#>>'{items,0,supportUnits}'='1'and jsonb_array_length(r->'items')=1,'actual_public_send_ranking');
 perform pg_temp.heart_assert(public.read_owned_mobile_fan_support_fans(c,'heart-fixture')#>>'{me,supportUnits}'='1'and public.read_owned_mobile_fan_support_fans(c,'heart-fixture')#>'{me,rank}'='null'::jsonb,'private_owner_me_totals_only');
 update public.social_profile_settings set profile_visible=false where app_user_id=b;
 perform pg_temp.heart_assert(jsonb_array_length(public.read_owned_mobile_fan_support_rankings(a)->'items')=0,'private_profile_excluded');
 update public.social_profile_settings set profile_visible=true where app_user_id=b;update public.social_favorite_visibility set visible=false where app_user_id=b;
 perform pg_temp.heart_assert(jsonb_array_length(public.read_owned_mobile_fan_support_rankings(a)->'items')=0,'private_favorite_excluded');
 update public.social_favorite_visibility set visible=true where app_user_id=b;
 insert into public.user_blocks(app_user_id,blocked_app_user_id)values(b,a);
 perform pg_temp.heart_assert(jsonb_array_length(public.read_owned_mobile_fan_support_rankings(a)->'items')=0,'reverse_block_excluded');delete from public.user_blocks where app_user_id=b and blocked_app_user_id=a;
 update public.app_users set status='disabled'where id=b;
 perform pg_temp.heart_assert(jsonb_array_length(public.read_owned_mobile_fan_support_rankings(a)->'items')=0,'disabled_fan_excluded');update public.app_users set status='active'where id=b;
 perform pg_temp.heart_assert(public.get_fan_ticket_balance(c,creator)=5 and(select sum(points)from public.fan_score_ledger where app_user_id=c and celebrity_id=creator)=7,'old_draw5_and_XP7_preserved');
 cursor:=(public.read_owned_mobile_fan_support_wallet(b,'heart-fixture')->>'fanPointLedgerSequence')::bigint;
 r:=public.check_in_mobile_fan_support(b,'heart-fixture');source:=(r->>'sourceId')::uuid;
 perform pg_temp.heart_assert(r->>'awarded'='true'and r->>'replayed'='false','actual_checkin_source_proof');
 r:=public.read_owned_mobile_fan_support_reward(b,source,cursor,'heart-fixture');
 perform pg_temp.heart_assert(r->>'newlyAwarded'='true'and r#>>'{reward,sourceId}'=source::text and r#>>'{reward,amount}'='100','reward_newer_than_pre_mutation_cursor');
 perform pg_temp.heart_assert(public.read_owned_mobile_fan_support_reward(b,source,(r->>'ledgerSequence')::bigint,'heart-fixture')->>'newlyAwarded'='false'and public.check_in_mobile_fan_support(b,'heart-fixture')->>'replayed'='true','historical_reward_and_repeated_activity_never_new');
 perform pg_temp.heart_assert(public.read_owned_mobile_fan_support_reward(a,source,0,'heart-fixture')->>'newlyAwarded'='false','other_owner_has_no_new_reward_proof');
 insert into public.celebrities(id,slug,status,image_url,published_at,roles,primary_role)values('e8000000-0000-4000-8000-000000000011','heart-other','published','/fixture.webp',now(),'{creator}','creator');
 insert into public.celebrity_localizations(celebrity_id,locale,name,summary,image_alt)select 'e8000000-0000-4000-8000-000000000011',locale,'Other','Other','Other'from unnest(enum_range(null::public.content_locale))locale;
 perform pg_temp.heart_error(format('select public.read_owned_mobile_fan_support_reward(%L,%L,0,''heart-other'')',b,source),'INVALID');
 perform pg_temp.heart_assert(true,'source_bound_to_original_creator');
 perform pg_temp.heart_assert(not has_function_privilege('anon','public.send_owned_mobile_fan_support(uuid,uuid,text,text,integer)','execute')and not has_function_privilege('authenticated','public.read_owned_mobile_fan_support_wallet(uuid,text)','execute')and not has_table_privilege('service_role','public.mobile_fan_support_contributions','insert'),'RPC_and_table_privileges_denied');
 perform pg_temp.heart_error('update public.mobile_fan_support_contributions set units=2','append-only');
 update public.mobile_fan_economy_policies set retired_at=clock_timestamp()where celebrity_id=creator and kind='exchange';
 perform pg_temp.heart_assert(public.send_owned_mobile_fan_support(b,send_key,'heart-fixture','heart-v1',1)->>'replayed'='true','original_send_recovery_after_policy_retirement');
 perform pg_temp.heart_error(format('select public.send_owned_mobile_fan_support(%L,%L,''heart-fixture'',''heart-v1'',1)',c,extensions.gen_random_uuid()),'POLICY_UNCONFIGURED');
end $$;
select 'BASE_WALLET_JSON='||public.read_owned_mobile_fan_economy_wallet(owner,'heart-fixture')::text from public.heart_support_upgrade_snapshot order by owner;
select 'BASE_HISTORY_JSON='||public.read_owned_mobile_fan_economy_history(owner,'heart-fixture',100)::text from public.heart_support_upgrade_snapshot order by owner;
rollback;
